[{"order":1,"type":"heading","text":"Full-Text Search Integration in Firebase Firestore (Algolia & Typesense)"},{"order":2,"type":"paragraph","text":"Firebase Firestore is a powerful NoSQL document database, but it natively lacks advanced full-text search capabilities like stemming, typo tolerance, and faceted search. To achieve robust search experiences, developers typically integrate dedicated search engines like Algolia or Typesense by synchronizing Firestore data using Cloud Functions."},{"order":3,"type":"subheading","text":"Architecture Overview"},{"order":4,"type":"paragraph","text":"The standard architectural pattern involves listening to Firestore document writes using Firebase Cloud Functions. Whenever a document is created, updated, or deleted, the Cloud Function triggers a corresponding operation on your search engine's index via their respective client SDKs or REST APIs."},{"order":5,"type":"subheading","text":"Option 1: Integrating Algolia"},{"order":6,"type":"paragraph","text":"Algolia is a fully managed Search-as-a-Service solution that offers instant search results and great client-side libraries. First, install the Algolia search client in your Cloud Functions project."},{"order":7,"type":"code","text":"npm install algoliasearch"},{"order":8,"type":"paragraph","text":"Next, implement a Cloud Function to sync Firestore documents to Algolia upon creation or update."},{"order":9,"type":"code","text":"const functions = require('firebase-functions');
const admin = require('firebase-admin');
admin.initializeApp();

const algoliasearch = require('algoliasearch');
const client = algoliasearch(functions.config().algolia.appid, functions.config().algolia.apikey);
const index = client.initIndex('products');

exports.sendProductToAlgolia = functions.firestore.document('products/{productId}').onWrite((change, context) => {
  const document = change.after.exists ? change.after.data() : null;
  if (!document) {
    return index.deleteObject(context.params.productId);
  }
  document.objectID = context.params.productId;
  return index.saveObject(document);
});"},{"order":10,"type":"subheading","text":"Option 2: Integrating Typesense"},{"order":11,"type":"paragraph","text":"Typesense is an open-source, highly performant alternative to Algolia that you can self-host or run via Typesense Cloud. Install the Typesense Node.js client."},{"order":12,"type":"code","text":"npm install typesense"},{"order":13,"type":"paragraph","text":"Configure the Typesense client and create a synchronization Cloud Function similar to the Algolia implementation."},{"order":14,"type":"code","text":"const functions = require('firebase-functions');
const admin = require('firebase-admin');
const Typesense = require('typesense');

const typesenseClient = new Typesense.Client({
  nodes: [{ host: 'xxx.typesense.net', port: '443', protocol: 'https' }],
  apiKey: functions.config().typesense.apikey,
  connectionTimeoutSeconds: 2
});

exports.indexProductToTypesense = functions.firestore.document('products/{productId}').onWrite(async (change, context) => {
  const productId = context.params.productId;
  if (!change.after.exists) {
    return await typesenseClient.collections('products').documents(productId).delete();
  }
  const document = change.after.data();
  document.id = productId;
  return await typesenseClient.collections('products').documents().upsert(document);
});"},{"order":15,"type":"subheading","text":"Best Practices for Search Synchronization"},{"order":16,"type":"bullet_point","text":"Idempotency: Ensure your synchronization logic handles retries gracefully without creating duplicate entries."},{"order":17,"type":"bullet_point","text":"Data Normalization: Only sync the fields required for search and filtering to reduce index size and improve performance."},{"order":18,"type":"bullet_point","text":"Initial Data Population: Write a separate Node.js migration script to bulk-import existing Firestore collections into your search index during initial setup."}]
